-- ============================================================
-- CareConnect — Full demo seed
-- ============================================================
-- 50 users (3 admin, 22 caregivers, 25 care receivers)
-- 8 certifications, ~65 caregiver-certifications, 30 addresses,
-- ~45 diagnoses, ~55 medications, 150 appointments
-- (25 requested, 45 scheduled, 60 completed, 20 cancelled),
-- ~155 audit rows, ~140 messages, ~70 payments.
--
-- All users login with: Password123!  (bcrypt cost 12)
--
-- HOW TO RUN
-- ----------
-- 1. Have aiven-init.sql already applied (this file does not create tables)
-- 2. In Aiven SQL editor, paste this whole file and execute
-- 3. The TRUNCATE block at the top wipes existing demo rows. Run once.
--
-- Timestamps are anchored to NOW() so the dataset stays demo-ready
-- regardless of when the file is loaded.
-- ============================================================

USE CareConnect;

-- ── 0. Wipe existing demo data ──────────────────────────────
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE message;
TRUNCATE TABLE appointment_audit;
TRUNCATE TABLE payment;
TRUNCATE TABLE appointment;
TRUNCATE TABLE address;
TRUNCATE TABLE diagnosis;
TRUNCATE TABLE medication;
TRUNCATE TABLE caregiverCertification;
TRUNCATE TABLE certification;
TRUNCATE TABLE careReceiver;
TRUNCATE TABLE caregiver;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;


